// Only public static files are cached. API requests and callback URLs never enter Cache Storage.
const CACHE='astra-production-v1';const STATIC=new Set(["index.html","notes.html","discover.html","ai.html","login.html","auth-callback.html","reset-password.html","profile.html","offline.html","admin/index.html","admin/users.html","admin/ai-management.html","admin/jarvis.html","admin/movies.html","admin/settings.html","manifest.json","assets/css/style.css","assets/icons/apple-touch-icon.png","assets/icons/icon-192.png","assets/icons/icon-512.png","assets/icons/icon.svg","assets/icons/tmdb.svg","assets/images/pets/nova.svg","assets/images/pets/orbit.svg","assets/images/pets/prism.svg","assets/js/admin-runtime-ui.js","assets/js/admin-ui.js","assets/js/app.js","assets/js/auth-operations.js","assets/js/auth-page.js","assets/js/auth-service.js","assets/js/chat-ui.js","assets/js/data-service.js","assets/js/device-session.js","assets/js/errors.js","assets/js/icons.js","assets/js/movie-ui.js","assets/js/pets.js","assets/js/runtime-ui.js","assets/js/services/admin-service.js","assets/js/services/chat-service.js","assets/js/services/jarvis-service.js","assets/js/services/movie-service.js","assets/js/services/runtime-service.js","assets/js/services/workspace-service.js","assets/js/supabase-client.js","assets/js/theme.js","assets/js/vendor/markdown.js","assets/js/vendor/supabase.js"]);
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll([...STATIC].map(p=>new URL(p,self.registration.scope).href))).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('astra-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url),scope=new URL(self.registration.scope);if(e.request.method!=='GET'||u.origin!==scope.origin)return;const file=u.pathname.slice(scope.pathname.length);if(u.search||u.hash||!STATIC.has(file))return;e.respondWith(fetch(e.request,{cache:'no-store'}).catch(async()=>e.request.mode==='navigate'?await caches.match(new URL('offline.html',scope).href):await caches.match(new URL(file,scope).href)||await caches.match(new URL('offline.html',scope).href)));});

self.addEventListener('push',event=>event.waitUntil(self.registration.showNotification('ASTRA',{body:'Yeni bildirişin var. Tətbiqi açaraq baxa bilərsən.',icon:new URL('assets/icons/icon-192.png',self.registration.scope).href,badge:new URL('assets/icons/icon-192.png',self.registration.scope).href,tag:'astra-update'})));
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(self.clients.openWindow(new URL('index.html',self.registration.scope).href));});
